return items.map((item, i) => {
  let toolsWanted = [];
  const m = (item.json.text || "").match(/\[[\s\S]*\]/);
  if (m) { try { toolsWanted = JSON.parse(m[0]); } catch (e) { toolsWanted = []; } }

  const classification = $('Merge Classification').all()[i].json;
  const toolResults = {};

  if (toolsWanted.includes('lookup_policy')) {
    toolResults.policy = MOCK_POLICY[classification.category] || { requires_extra_security_check: false };
  }
  if (toolsWanted.includes('lookup_user_history')) {
    const past = USER_HISTORY[classification.user_id] || [];
    toolResults.user_history = {
      past_requests_90d: past.length,
      past_requests_summary: past,
    };
  }

  return {
    json: {
      ...classification,
      tools_called: toolsWanted,
      tool_results: toolResults,
    }
  };
});

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const records = JSON.parse(buffer.toString('utf-8'));

return records.map(r => ({ json: r }));

