return items.map((item, i) => {
  const original = $('Split Records').all()[i].json;
  const parsed = extractJson(item.json.text) || {};
  return {
    json: {
      ...original,
      category: parsed.category || "other",
      urgency: parsed.urgency || "medium",
    }
  };
});

