function extractJson(text) {
  const match = (text || "").match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch (e) { return null; }
}

const items = $input.all();

return items.map((item, i) => {
  const base = $('Call Tools').all()[i].json;

  const raw = [
    $('Assess 1').all()[i].json,
    $('Assess 2').all()[i].json,
    $('Assess 3').all()[i].json,
  ];

  const samples = raw.map(r => {
    const o = extractJson(r.text) || {};
    return {
      category: o.category || base.category,
      urgency: o.urgency || base.urgency,
      recommended_action: o.recommended_action || "escalate",
    };
  });

  const triples = samples.map(s => s.category + "|" + s.urgency + "|" + s.recommended_action);
  const counts = {};
  triples.forEach(t => { counts[t] = (counts[t] || 0) + 1; });

  let best = triples[0];
  for (const t of triples) {
    if (counts[t] > counts[best]) best = t;
  }

  const confidence = Math.round((counts[best] / triples.length) * 100) / 100;
  const parts = best.split("|");

  return {
    json: {
      ...base,
      recommendation: {
        category: parts[0],
        urgency: parts[1],
        recommended_action: parts[2],
        confidence: confidence,
      },
      needs_human_review: confidence < 0.6,
    }
  };
});

const VALID_CATEGORIES = ["hardware", "software", "access", "network", "other"];

const MOCK_POLICY = {
  hardware: { requires_extra_security_check: false },
  software: { requires_extra_security_check: false },
  access:   { requires_extra_security_check: true  },
  network:  { requires_extra_security_check: false },
  other:    { requires_extra_security_check: false },
};

return $input.all().map(item => {
  const base = item.json;
  const rec = base.recommendation || {};
  const category = rec.category || base.category;
  const urgency = rec.urgency || base.urgency;

  let decision;
  let policyRecheck = false;

  if (VALID_CATEGORIES.indexOf(category) === -1) {
    decision = "escalate";
  } else {
    const policy = MOCK_POLICY[category] || { requires_extra_security_check: false };
    policyRecheck = policy.requires_extra_security_check;
    decision = policyRecheck ? "escalate" : (urgency === "low" ? "auto_approve" : "escalate");
  }

  return {
    json: { ...base, decision: decision, policy_recheck: policyRecheck }
  };
});

return $input.all().map(item => {
  const base = item.json;
  const rec = base.recommendation || {};
  const urgency = rec.urgency || base.urgency;

  let actionResult;
  if (base.needs_human_review) {
    actionResult = "[MOCK] Notification sent: Request " + base.request_id + " flagged for human review";
  } else if (base.decision === "auto_approve") {
    actionResult = "[MOCK] Notification sent: Request " + base.request_id + " auto-approved";
  } else {
    actionResult = "[MOCK] Ticket created: priority=" + urgency + ", assigned_to=IT_general";
  }

  return { json: { ...base, action_result: actionResult } };
});

const records = $input.all().map(item => item.json);
const text = JSON.stringify(records, null, 2);

return [{
  json: { count: records.length },
  binary: {
    data: {
      data: Buffer.from(text, 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'run2_n8n_llama_raw.json',
    }
  }
}];
